function stkSocialBar(brand, dark) {
  return (g, p) => {
    const L = -140;
    const R = 140;
    const H = 22;
    const bar = () => stkRR(g, L, -H, R - L, H * 2, H);
    g.save();
    g.shadowColor = "rgba(0,0,0,0.35)";
    g.shadowBlur = 8;
    g.shadowOffsetY = 3;
    bar();
    g.fillStyle = dark ? "rgba(22,24,30,0.9)" : "rgba(255,255,255,0.96)";
    g.fill();
    g.restore();
    g.lineWidth = 4;
    g.strokeStyle = dark && brand.accent === "#111111" ? "#ffffff" : brand.accent;
    bar();
    g.stroke();
    const q = (p - 0.3) / 0.35;
    if (q > 0 && q < 1) {
      g.save();
      bar();
      g.clip();
      const x = L - 40 + (R - L + 80) * q;
      const shine = g.createLinearGradient(x - 24, 0, x + 24, 0);
      shine.addColorStop(0, "rgba(255,255,255,0)");
      shine.addColorStop(0.5, `rgba(255,255,255,${dark ? 0.22 : 0.85})`);
      shine.addColorStop(1, "rgba(255,255,255,0)");
      g.fillStyle = shine;
      g.transform(1, 0, -0.4, 1, 0, 0);
      g.fillRect(x - 24, -H, 48, H * 2);
      g.restore();
    }
    const beat = 1 + 0.12 * Math.exp(-(p * 2 % 1) * 8);
    g.save();
    g.translate(R, 0);
    g.scale(beat, beat);
    stkPaint(g, () => stkCirc(g, 0, 0, 16), dark && brand.accent === "#111111" ? "#ffffff" : brand.accent, 4);
    g.strokeStyle = dark && brand.accent === "#111111" ? "#111111" : "#ffffff";
    g.lineWidth = 4;
    g.lineCap = "round";
    stkLine(g, -7, 0, 7, 0);
    stkLine(g, 0, -7, 0, 7);
    g.restore();
    const ding = p < 0.25 ? Math.sin(p / 0.25 * Math.PI * 3) * (1 - p / 0.25) : 0;
    const s = 1 + 0.05 * Math.sin(p * TAU);
    g.save();
    g.translate(L, 0);
    g.rotate(ding * 0.35);
    g.scale(s, s);
    brand.logo(g);
    g.restore();
    stkSparkle(g, R - 26, -H - 4, 7 * Math.max(0, Math.sin(p * TAU)), dark ? "#ffffff" : "#ffd23f");
  };
}
